### 三道门骨架

```python
class SafetyGates:
    def __init__(self, decision_model, policy):
        self.D = decision_model   # Jev or Decisions API
        self.P = policy           # shared safety policy

    def task_gate(self, task, obs0):
        return self.D.review(task, obs0, self.P, level='task')

    def action_gate(self, action, obs):
        return self.D.review(action, obs, self.P, level='action')

    def commit_gate(self, commit, obs):
        # irreversible ops: release, gripper close, memory write
        return self.D.review(commit, obs, self.P, level='commit')

def guarded_episode(planner, gates, env):
    obs = env.reset()
    if gates.task_gate(env.task, obs).verdict == 'refuse':
        return {'aborted': True, 'reason': 'task_gate'}
    for step in range(env.horizon):
        action = planner(obs, env.task)
        if gates.action_gate(action, obs).verdict != 'allow':
            continue
        if env.is_irreversible(action):
            if gates.commit_gate(action, obs).verdict != 'allow':
                continue
        obs = env.step(action)
    return {'aborted': False}
```

第 6 步别省：一旦 Agent 有长期记忆，「写脏记忆」比「做错一步」更隐蔽，也让 S 类风险成为持续在线系统里最难查的一支。
